function settingsScreen(){
 const t=activeTab||'identity',s=db.settings;
 let content='';
 if(t==='identity')content=`<form id="settings-form"><input type="hidden" name="tab" value="identity"><div class="form-grid">${formField('school','School name','text',s.school)}${formField('tagline','Tagline','text',s.tagline)}${formField('logo','School monogram','text',s.logo)}${formField('currency','Currency','currency',s.currency)}${formField('timezone','Timezone','timezone',s.timezone)}${formField('dateFormat','Date display','dateFormat',s.dateFormat)}</div><div class="form-actions">${button('Save school preferences','submit','','primary','check','type="submit"')}</div></form>`;
 if(t==='academic')content=`<form id="settings-form"><input type="hidden" name="tab" value="academic"><div class="form-grid">${formField('academicYear','Current academic year','text',s.academicYear)}${formField('term','Current term','text',s.term)}</div><h3>Module configuration</h3>${['Attendance','Academics','Finance','Communication'].map(m=>`<label class="switch"><span>${m}<small>Included in this demo’s module map</small></span><input name="module-${m}" type="checkbox" ${s.modules.includes(m)?'checked':''}></label>`).join('')}<p class="muted text-small">Module preferences are recorded for the implementation contract. Demo routes remain available for design review.</p><div class="form-actions">${button('Save academic settings','submit','','primary','check','type="submit"')}</div></form>`;
 if(t==='security')content=alertBox('Frontend demonstration','Production authentication, encryption, privacy enforcement, and server-side authorization are not implemented.')+`<form id="settings-form"><input type="hidden" name="tab" value="security"><label class="switch"><span>Require two-factor authentication<small>Production security policy, saved as a design preference</small></span><input name="twoFactor" type="checkbox" ${s.twoFactor?'checked':''}></label>${formField('sessionMinutes','Session timeout (minutes)','number',s.sessionMinutes)}${formField('retention','Audit retention preference','text',s.retention)}${formField('privacy','Record privacy policy','text',s.privacy)}<div class="form-actions">${button('Save security preferences','submit','','primary','check','type="submit"')}</div></form><div class="form-actions">${button('Preview session expired','go','expired')}${button('Preview access denied','go','denied')}</div>`;
 if(t==='notifications')content=`<form id="settings-form"><input type="hidden" name="tab" value="notifications">${[['messaging','Enable parent–teacher messaging','Controls portal access to teacher conversations.'],['attendanceNotifications','Attendance notification requests','Create a communication record after an absence is submitted.'],['notificationEmail','Email notifications','Save preference; email service is disconnected.'],['notificationWhatsapp','WhatsApp notifications','Save preference; WhatsApp service is disconnected.'],['weeklyReport','Weekly owner reports','Save preference; no automated report service is running.']].map(([key,t,d])=>`<label class="switch"><span>${t}<small>${d}</small></span><input type="checkbox" name="${key}" ${s[key]?'checked':''}></label>`).join('')}<div class="form-actions">${button('Save notification settings','submit','','primary','check','type="submit"')}</div></form>`;
 if(t==='backup')content=alertBox('Demo snapshots only','Export and restore this browser’s demo data. This is not an operational school backup service.')+`<div class="two-col"><div class="panel flat"><h2>Download a snapshot</h2><p class="muted text-small">Includes the demo’s local records, preferences, and audit events.</p>${button('Download JSON snapshot','backup','','','download')}</div><div class="panel flat"><h2>Restore a snapshot</h2><p class="muted text-small">Replace this browser’s demo data with a previously exported snapshot.</p><input id="restore-file" type="file" accept=".json" class="field" aria-label="Choose demo backup JSON"></div></div><div class="form-actions">${button('Reset demo records','reset','','danger','refresh')}</div>`;
 return heading('A school system that fits your school.','Owner settings apply across the demo network. Every change is audited.','','SYSTEM SETTINGS')+tabs([['identity','School identity'],['academic','Academic & modules'],['security','Security & privacy'],['notifications','Notifications'],['backup','Backup & recovery']],t)+panel(({identity:'Identity & regional preferences',academic:'Academic calendar & modules',security:'Security & privacy preferences',notifications:'Notification policies',backup:'Backup & recovery'}[t]),content);
}
function rolesScreen(){
 return heading('Clear responsibility. Controlled access.','Permission rules always include branch, class, child, and record scope.',button('Create role','create','roles','primary','plus'),'ROLES & PERMISSIONS')+
 alertBox('Prototype access controls','Routes, records, totals, and actions use the same client-side scope checks. Production requires authenticated, server-side authorization.')+
 panel('Role & permission matrix',table(['Role','Record scope','View','Create','Edit','Approve','Export','Delete'],PERMISSION_MATRIX.map(x=>`<tr><td><strong>${x.role}</strong></td><td>${x.scope}</td>${['view','create','edit','approve','export','delete'].map(k=>`<td>${esc(x[k])}</td>`).join('')}</tr>`)))+
 `<div class="two-col mt">${panel('Custom roles',table(['Role','Scope','Status',''],scope(db.roles).map(x=>`<tr><td><strong>${esc(x.name)}</strong><small>${x.permissions?.join(', ')||'No grants'}</small></td><td>${x.scope}</td><td>${status(x.status)}</td><td>${button('Configure','detail','roles:'+x.id,'small')}</td></tr>`)),button('Create','create','roles','small','plus'),'Custom roles are design records; the demo accounts use the baseline and overrides below.')}${panel('Explicit overrides',`<p class="muted text-small">Limit an existing demo account’s create, edit, export, approve, or publish action. Scope restrictions cannot be expanded. Confirmation and a reason are required.</p>${button('Configure override','permissionOverride','','','shield')}<div class="timeline">${(db.overrides||[]).map(o=>`<p>${ROLE_NAMES[o.role]} · ${TITLES[o.module]} · ${o.action}<br>${status(o.allowed?'Baseline restored':'Denied')}<small>${esc(o.reason)} · ${o.actor}</small></p>`).join('')||'<p>No explicit overrides recorded.</p>'}</div>`)}</div>`;
}
function auditScreen(){const rows=filtered(scope(db.audit));return heading('A record of every important change.','Who acted, what changed, when, and which campus was affected.',button('Export audit log','export','audit','','download'),'AUDIT TRAIL')+panel('Activity history',toolbar(scope(db.audit))+table(['Action / record','Actor','School / branch','Before → after','Time'],rows.slice((page-1)*7,page*7).map(a=>`<tr><td><strong>${esc(a.name)}</strong><small>${esc(a.target)}</small></td><td>${esc(a.actor)}</td><td>${esc(branchName(a.branch))}</td><td style="max-width:230px;white-space:normal">${esc(a.before||'—')} → ${esc(a.after||'—')}</td><td>${esc(a.date)}</td></tr>`))+paginate(rows.length))}
function reportsScreen(){const financial=['owner','office'].includes(role);return heading('Make the next decision a clear one.','Reports inherit the active branch, academic year, and account permissions.',button('Generate report','reportGenerate','','primary','download'),'REPORTS & INSIGHTS')+
 panel('Report builder',`<form id="report-form"><div class="form-grid">${formField('reportType','Report','reportType',financial?'Financial reconciliation':'Daily school summary')}${formField('from','From','date','2026-10-01')}${formField('to','To','date',TODAY)}<div class="form-field"><label>Scope</label><div class="field">${esc(branchName(branch))} · ${db.academicYear}</div><small>Controlled by the active account and branch.</small></div></div><div class="form-actions">${button('Print current view','print','','','print')}${button('Generate & download','submit','','primary','download','type="submit"')}</div><div class="error-text" id="report-error" role="alert"></div></form>`)+
 `<div class="cards mt">${[['Daily school summary','Attendance, new admissions, approvals, and school activity.','school'],['Weekly owner report','A campus snapshot prepared for the owner.','chart'],[financial?'Financial reconciliation':'Academic performance',financial?'Confirmed payments, expenses, outstanding fees, and mismatches.':'Approved results, lesson plan reviews, and student progress.','file']].map(([t,d,i])=>`<article class="panel"><div class="panel-head"><h2>${t}</h2>${icon(i)}</div><p class="muted text-small">${d}</p>${button('Select report','selectReport',t,'small ghost','arrow')}</article>`).join('')}</div>`;
}
function profileScreen(){const s=isPortal()?db.students.find(s=>s.id===child):null;return heading('Your school identity.','Manage your demo profile, documents, and notification preferences.',button('Sign out of demo','go','signin','','logout'),'PROFILE')+`<div class="split"><div class="stack">${panel('Profile details',`<div style="display:flex;align-items:center;gap:18px"><span class="avatar purple" style="width:65px;height:65px;font-size:22px">${account().initials}</span><div><h2>${account().name}</h2><span class="muted text-small">${ROLE_NAMES[role]} · Demo account</span></div></div><div class="detail-grid"><div class="detail-item"><small>School</small><b>${esc(db.settings.school)}</b></div><div class="detail-item"><small>Branch access</small><b>${role==='owner'?'All authorized campuses':branchName(branch)}</b></div><div class="detail-item"><small>Current academic year</small><b>${db.academicYear}</b></div><div class="detail-item"><small>Timezone</small><b>${db.settings.timezone}</b></div>${s?`<div class="detail-item"><small>Student</small><b>${s.name}</b></div><div class="detail-item"><small>Class / roll</small><b>${s.class} / ${s.roll}</b></div>`:''}</div>${button('Edit contact preferences','profileEdit','','','edit')}`)}${isPortal()?panel('Profile & documents',scope(db.documents,'documents').map(d=>`<div class="document">${icon('file')}<div><b>${d.name}</b><small>${date(d.date)}</small></div>${button('Download','documentDownload',d.id,'small','download')}</div>`).join('')||empty()):''}</div><div class="stack">${panel('Notification preferences',`<form id="profile-preferences"><label class="switch"><span>WhatsApp updates<small>Preference only · messaging service disconnected</small></span><input type="checkbox" name="whatsapp" ${db.profilePrefs?.[role]?.whatsapp?'checked':''}></label><label class="switch"><span>In-app notices<small>School announcements and activity</small></span><input type="checkbox" name="inapp" ${db.profilePrefs?.[role]?.inapp!==false?'checked':''}></label><div class="form-actions">${button('Save preferences','submit','','primary','','type="submit"')}</div></form>`)}${panel('Explore the prototype',`<p class="muted text-small">Each demo account has a distinct set of records and capabilities. The role switcher is a review tool.</p>${button('Choose demo account','roles','','full','users')}<div class="mt">${link('Design reference & coverage','design','full','book')}</div>`)}</div></div>`}
function notificationsScreen(){const rows=scope(db.notifications,'notifications').filter(n=>n.roles.includes(role)&&(!isPortal()||!n.student||n.student===child));return heading('A little less to keep in your head.','Updates relevant to your account and active scope.',button('Mark all as read','readNotifications','','','check'),'NOTIFICATIONS')+panel('Your notifications',rows.map(n=>`<div class="approval"><div class="approval-icon">${icon(n.read?'check':'bell')}</div><div style="flex:1"><b>${esc(n.name)}</b><small>${esc(n.date)} · ${branchName(n.branch)}</small></div>${!n.read?status('Unread'):''}${button('Open','notificationOpen',n.id,'small ghost','chevron')}</div>`).join('')||empty('You’re all caught up','Relevant school updates will appear here.'))}
function timetableScreen(){
 let cls=isPortal()?studentClass():classFilter;
 return heading('A little structure. Room to grow.','Weekly timetable · '+cls+' · '+esc(db.settings.term),['owner','principal'].includes(role)?button('Submit timetable','create','timetables','primary','plus'):'','TIMETABLE')+
 panel('Weekly schedule',`<div class="toolbar">${!isPortal()?`<select id="attendance-class" aria-label="Select timetable class">${(role==='teacher'?account().classes:['9 A','9 B','6 B']).map(c=>`<option ${c===cls?'selected':''}>${c}</option>`).join('')}</select>`:''}${button('Print timetable','print','','small','print')}<span class="muted text-small">Illustrative published schedule · pending changes remain in the review queue.</span></div><div class="table-wrap"><div class="schedule"><div></div>${['Monday','Tuesday','Wednesday','Thursday','Friday'].map(d=>`<div style="text-align:center;font-weight:600">${d}</div>`).join('')}${['09:00','10:00','10:30','12:00','14:00'].map((tm,i)=>`<div class="period">${tm}</div>${['English','Mathematics','Science','Hindi','Social science'].map((_,j)=>`<div class="lesson ${i===2&&j===2?'current':''}"><b>${['Science','Mathematics','English','Hindi','Social science'][(i+j)%5]}</b><small>Class ${cls}<br>${i===2&&j===2?'Lab 02 · Priya Nair':'Room 104'}</small></div>`).join('')}`).join('')}</div></div>`)+(['owner','principal'].includes(role)?genericList('timetables',{desc:'Review proposed schedule changes before approval.'}):'');
}
function examsScreen(){return genericList('exams',{desc:isPortal()?'Approved exam schedules and published results for your class.':'Plan examinations, review dates, and approve schedules.'})+panel('Published report cards',table(['Assessment','Class','Result',''],scope(db.marks,'marks').filter(m=>m.status==='Approved').map(m=>`<tr><td><strong>${m.name}</strong></td><td>${m.class}</td><td>${status('Approved')}</td><td>${isPortal()?button('Download report card','reportCard',m.id,'small','download'):button('View marks','detail','marks:'+m.id,'small','chart')}</td></tr>`)))}
function calendarScreen(){return heading('Good things ahead.','Holidays, meetings, and events across your school calendar.',can('create','calendar')?button('Add event','create','calendar','primary','plus'):'','CALENDAR')+panel('Upcoming at school',toolbar(scope(db.calendar)), '', 'Dates are illustrative demo data.')+`<div class="cards">${filtered(scope(db.calendar)).map(e=>`<article class="panel branch-card"><div class="panel-head">${status(e.type)}<span class="muted text-small">${date(e.date)}</span></div><h3>${esc(e.name)}</h3><p>${esc(e.notes)}</p>${button('View event','detail','calendar:'+e.id,'full mt')}</article>`).join('')||empty()}</div>`}
function announcementsScreen(){return heading('One school. A shared conversation.','School and class announcements for your audience.',can('create','announcements')?button('Create announcement','create','announcements','primary','plus'):'','ANNOUNCEMENTS')+toolbar(scope(db.announcements,'announcements'))+`<div class="cards">${filtered(scope(db.announcements,'announcements')).map(a=>`<article class="panel branch-card"><div class="panel-head">${status(a.status)}<small class="muted">${date(a.date)}</small></div><h3>${esc(a.name)}</h3><p>${esc(a.notes)}</p><p>Audience · ${a.audience}</p>${button('Open announcement','detail','announcements:'+a.id,'full mt')}</article>`).join('')||empty()}</div>`}
function documentsScreen(){
 return genericList('documents',{desc:'Certificates, documents, receipts, and downloadable reports in your assigned scope.'})+(['owner','office','parent','student'].includes(role)?panel('Confirmed payment receipts',paymentsTable()):'')+(isPortal()?panel('Available report cards',scope(db.marks,'marks').filter(m=>m.status==='Approved').map(m=>`<div class="document">${icon('chart')}<div><b>${m.name}</b><small>Approved results only</small></div>${button('Report card','reportCard',m.id,'small','download')}</div>`).join('')):'');
}
function authScreen(type){
 const welcome=type==='signin',expired=type==='expired';
 return `<div class="auth-wrap"><div class="auth-art"><div class="logo mb">${icon('book')}</div><div class="eyebrow">SCHOOL MANAGEMENT SYSTEM v2.0</div><div class="big">More connected.<br>More possibilities.</div><p>A calmer school day starts with everything in the right place.</p><div class="legend mt"><span>Smart</span><span>Secure</span><span>Connected</span></div></div><div class="auth-card"><div class="eyebrow">GREENWOOD INTERNATIONAL SCHOOL</div><h1>${welcome?'Welcome to your school.':expired?'Your session has expired.':'Let’s get you back in.'}</h1><p>${welcome?'Choose a demo account to explore a complete school day.':expired?'Your saved demo work is still here. Sign in again to continue.':'Password recovery is a design preview. No recovery email will be sent.'}</p>${expired?button('Return to sign in','go','signin','primary','lock'):welcome?`<form id="signin-form">${formField('account','Demo account','account',role)}${formField('email','Email address','email','demo@greenwood.example.test')}${formField('password','Demo password','password','schoolspace')}<small class="muted">Demo only · any password with 6+ characters</small><div class="form-actions">${button('Open demo workspace','submit','','primary','arrow','type="submit"')}</div></form><div style="display:flex;justify-content:space-between;margin-top:18px">${link('Forgot password?','recovery','small ghost')}${link('Design reference','design','small ghost')}</div>`:`<form id="recovery-form">${formField('email','School account email','email','')}<div class="form-actions">${button('Preview recovery request','submit','','primary','mail','type="submit"')}</div><div id="recovery-result" role="status"></div></form>${link('Back to sign in','signin','full small mt')}`}<div class="mt">${alertBox('Interactive prototype','No real school accounts, payment processing, or external message sending are connected.')}</div></div></div>`;
}
